const $=s=>document.querySelector(s);const foods=[['🍜','Noodles'],['🍄','Mushroom'],['🥬','Greens'],['🌶️','Spice'],['🥚','Egg'],['🧈','Butter'],['🌽','Corn'],['🧄','Garlic']];
const toppingNames=['','Forest','Garden','Dragon','Golden egg','Velvet butter','Harvest corn','Moon garlic'];
const oldNames=new Map([['0,1','Forest ramen'],['0,2','Garden bowl'],['0,3','Dragon ramen'],['0,1,2','Moonlight special'],['0,1,3','Firefly feast']]);
// Every distinct set of one, two, or three toppings, over a noodle base.
const dishes=[];
for(let size=1;size<=3;size++){
  function combine(start,chosen){
    if(chosen.length===size){
      const recipe=[0,...chosen],key=recipe.join(',');
      const name=oldNames.get(key)||(size===1?toppingNames[chosen[0]]+' ramen':chosen.map(i=>foods[i][1]).join(' & ')+(size===2?' bowl':' feast'));
      dishes.push({name,recipe,price:4+size*4+(chosen.includes(3)?2:0)});
      return;
    }
    for(let i=start;i<foods.length;i++)combine(i+1,[...chosen,i]);
  }
  combine(1,[]);
}
const availableDishes=()=>dishes.filter(d=>d.recipe.length<=Math.min(4,night+1));
const names=['Mochi','Bramble','Pip','Clover','Nimbus','Fern','Tofu','Boba'];let saved;try{saved=JSON.parse(localStorage.getItem('moonbowl-v1'))}catch{}let bank=saved?.bank||0,night=saved?.night||1,levels=saved?.levels||[0,0,0],customers=[],selected=0,bowl=[],remaining=60,running=false,paused=false,served=0,earned=0,streak=0,last=0;const save=()=>{try{localStorage.setItem('moonbowl-v1',JSON.stringify({bank,night,levels}))}catch{}};const icons=r=>r.map(i=>foods[i][0]).join(' ');function addCustomer(slot){const menu=availableDishes();const dish=menu[Math.floor(Math.random()*menu.length)];customers[slot]={name:names[Math.floor(Math.random()*names.length)],skin:['#a7bd9b','#b6a1cd','#e8af91','#99bdc2'][Math.floor(Math.random()*4)],dish,patience:1,max:32+levels[1]*9};renderCustomers()}function renderCustomers(){ $('#customers').innerHTML=customers.map((c,i)=>`<button class="customer ${selected===i?'selected':''}" data-slot="${i}" aria-label="Select ${c.name}: ${c.dish.name}, ${c.dish.recipe.map(f=>foods[f][1]).join(', ')}"><div class="order">${c.dish.name}<span class="recipe">${icons(c.dish.recipe)}</span><div class="patience"><i style="width:${c.patience*100}%"></i></div></div><div class="monster" style="--skin:${c.skin};animation-delay:-${i}s"><i class="ears"></i><i class="blush"></i><span class="customer-name">${c.name}</span></div></button>`).join('');document.querySelectorAll('.customer').forEach(b=>b.onclick=()=>{if(!running||paused)return;selected=+b.dataset.slot;renderCustomers();hint(`${customers[selected].name} would love ${customers[selected].dish.name.toLowerCase()}.`)})}function hint(t){$('#hint').textContent=t}function renderBowl(){$('#bowl').textContent=bowl.length?'🍲':'🥣';$('#dishname').textContent=bowl.length?'A little something delicious':'An empty bowl of possibilities';$('#ingredients').textContent=bowl.length?bowl.map(i=>foods[i][1]).join(' + '):'Tap ingredients below to start cooking'}function stats(){$('#coins').textContent=bank;$('#menu-count').textContent=availableDishes().length+' / '+dishes.length+' recipes';$('#night').textContent=`NIGHT ${String(night).padStart(2,'0')}`;$('#served').textContent=served;$('#time').textContent=`☾ ${Math.ceil(remaining)}s`}$('#pantry').innerHTML=foods.map(([icon,name],i)=>`<button class="ingredient" data-food="${i}"><span>${icon}</span>${name}</button>`).join('');document.querySelectorAll('.ingredient').forEach(b=>b.onclick=()=>{if(!running||paused)return;if(bowl.length>=4){hint('Bowl is full! Clear it with ↺ to start again.');return}bowl.push(+b.dataset.food);renderBowl()});$('#clear').onclick=()=>{if(running&&!paused){bowl=[];renderBowl()}};$('#serve').onclick=()=>{if(!running||paused)return;const c=customers[selected];if([...bowl].sort().join()!=[...c.dish.recipe].sort().join()){hint('Almost! Match the ingredients in the selected order.');streak=0;return}streak++;const tip=(c.patience>.5?2:0)+levels[0]*2+(streak>=3?3:0);const amount=c.dish.price+tip;bank+=amount;earned+=amount;served++;hint(`${c.name}: “So cozy! Thank you.” +${amount} ✦`);$('#combo').textContent=streak>=3?`${streak} bowl streak! +3 ✦`:'made with magic ✧';bowl=[];renderBowl();addCustomer(selected);stats();save()};function start(){remaining=60+levels[2]*10;served=0;earned=0;streak=0;bowl=[];selected=0;customers=[];for(let i=0;i<3;i++)addCustomer(i);running=true;paused=false;$('#pause').textContent='Ⅱ';$('#overlay').classList.add('hidden');renderBowl();stats();hint(availableDishes().length+' recipes tonight! Match the selected order.');last=performance.now()}function end(){running=false;night++;save();showShop()}function showShop(){const upgradeNames=['Golden broth','Comfy waiting stools','Moonlit lanterns'];const desc=['+2 stars per bowl','Customers wait 9s longer','Nights last 10s longer'];$('#overlay').innerHTML=`<section class="modal"><div class="eyebrow">THE LANTERNS ARE GLOWING LOW</div><div class="hero-icon">🌙</div><h1 style="font-size:36px">A lovely little night.</h1><p>${served} happy customers · ${earned} stars earned<br>You have <b>${bank} ✦</b> to make this place your own.</p>${upgradeNames.map((n,i)=>{const cost=25*(levels[i]+1);return `<button class="upgrade" data-upgrade="${i}" ${bank<cost||levels[i]>=5?'disabled':''}><span>${n} · Lv ${levels[i]}<br><small>${desc[i]}</small></span><b>${levels[i]>=5?'MAX':cost+' ✦'}</b></button>`}).join('')}<button id="next" class="primary">Open night ${night} <span>↗</span></button><small>Night 1: 7 recipes · Night 2: 28 · Night 3+: 63<br>Every upgrade is saved automatically.</small></section>`;$('#overlay').classList.remove('hidden');$('#next').onclick=start;document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{const i=+b.dataset.upgrade,cost=25*(levels[i]+1);if(bank>=cost&&levels[i]<5){bank-=cost;levels[i]++;save();stats();showShop()}})}$('#start').onclick=start;$('#pause').onclick=()=>{if(!running)return;paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Resume game':'Pause game');$('#game').classList.toggle('paused',paused);hint(paused?'Take your time. The market is paused.':'Welcome back to your little kitchen.')};document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!paused)$('#pause').click()});function frame(t){const dt=Math.min((t-last)/1000,.2);last=t;if(running&&!paused){remaining-=dt;customers.forEach((c,i)=>{c.patience-=dt/c.max;if(c.patience<=0){streak=0;hint(`${c.name} headed home. Another friend is here!`);addCustomer(i)}});document.querySelectorAll('.patience i').forEach((el,i)=>{el.style.width=customers[i].patience*100+'%';el.style.background=customers[i].patience<.25?'#c47a76':'#76a68a'});stats();if(remaining<=0)end()}requestAnimationFrame(frame)}stats();for(let i=0;i<3;i++)addCustomer(i);requestAnimationFrame(frame);
